          sycl::nd_range<1>(sycl::range<1>(static_cast<size_t>(grid_size) * block_size),
                            sycl::range<1>(static_cast<size_t>(block_size))),
          [=](sycl::nd_item<1> it) {
            atomic_reduction_v<V>(in, out, arrayLength, it);
          });
